from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

# Initialize the Azure Form Recognizer client
endpoint = "https://<your-form-recognizer-endpoint>.cognitiveservices.azure.com/"
key = "<your-azure-form-recognizer-key>"
credential = AzureKeyCredential(key)
document_analysis_client = DocumentAnalysisClient(
    endpoint=endpoint, credential=credential
)

# Upload document and analyze layout
def extract_layout_from_document(document_bytes):
    poller = document_analysis_client.begin_analyze_document(
        "prebuilt-layout", document_bytes
    )
    result = poller.result()

    layout_elements = {
        "blocks": [],
        "lines": [],
        "tables": [],
        "page_count": len(result.pages)
    }

    for page in result.pages:
        for paragraph in page.paragraphs:
            layout_elements["blocks"].append({
                "text": paragraph.text,
                "bounding_box": page.bounding_box,
                "type": "block"
            })

        for line in page.lines:
            layout_elements["lines"].append({
                "text": line.text,
                "bounding_box": line.bounding_box,
                "type": "line"
            })

        for table in page.tables:
            table_data = {
                "cells": [],
                "bounding_box": table.bounding_box,
                "type": "table"
            }
            for cell in table.cells:
                table_data["cells"].append({
                    "text": cell.text,
                    "row_index": cell.row_index,
                    "column_index": cell.column_index,
                    "bounding_box": cell.bounding_box
                })
            layout_elements["tables"].append(table_data)

    return layout_elements
